using System;using System.IO;using System.Linq;using System.Collections;using IdleIntelligence.Core;using IdleIntelligence.Runtime;using NUnit.Framework;using UnityEngine;using UnityEngine.SceneManagement;using UnityEngine.UI;using UnityEngine.TestTools;
namespace IdleIntelligence.PlayTests {
 public sealed class DesignReviewTests {
  GameRuntime game;string directory;
  [UnitySetUp]public IEnumerator Setup(){directory=Path.Combine(Path.GetTempPath(),"idle-design-"+Guid.NewGuid());Directory.CreateDirectory(directory);GameRuntime.SavePathOverride=Path.Combine(directory,"save.json");yield return SceneManager.LoadSceneAsync("IdleIntelligence");yield return null;game=UnityEngine.Object.FindFirstObjectByType<GameRuntime>();game.Act(s=>NarrativeBridge.Action(s,"name","AURA"));for(int i=0;i<5;i++)game.Act(s=>NarrativeBridge.Action(s,"continue"));game.Act(s=>NarrativeBridge.Action(s,"skip-tutorial"));game.Show("hardware");yield return null;}
  [UnityTearDown]public IEnumerator Cleanup(){if(game!=null)UnityEngine.Object.Destroy(game.gameObject);yield return null;GameRuntime.SavePathOverride=null;}
  [UnityTest]public IEnumerator CaptureBaselineAndProveEditorAccess(){string output=game.GetComponent<MobileShell>()==null?"/tmp/idle-design-before":"/tmp/idle-design-after";Directory.CreateDirectory(output);foreach(int width in new[]{320,390,430}){WorkshopTests.Capture(width,width==320?568:width==390?844:932,output+"/labor-"+width+".png");yield return null;}File.WriteAllLines(output+"/scene-hierarchy.txt",UnityEngine.Object.FindObjectsByType<Transform>(FindObjectsSortMode.None).Select(t=>t.name));Assert.That(game.State.Hardware[0],Is.Zero);Assert.That(game.Act(s=>Game.Buy(s,"calculator",1)),Is.True);Assert.That(game.State.Hardware[0],Is.EqualTo(1));Debug.Log("DESIGN_CAPABILITY_PROOF scene=IdleIntelligence PlayMode=running console=readable captures=320,390,430 realPurchase=passed isolatedSave="+game.SavePath);}
  [UnityTest]public IEnumerator ReviewMobileSection(){
   string output="/tmp/idle-design-review";Directory.CreateDirectory(output);game.Act(s=>{var n=s.Copy();n.Legacy.prepared=true;n.Story.seen=NarrativeCatalog.Dialogues.Select(d=>d.Id).ToArray();n.Story.enabled=false;n.Credits=ScientificNumber.From(50000);n.Workshop.inventory=ItemBalance.Items.Take(6).Select((d,i)=>new ItemInstance{id="design-"+i,type=d.Id,rarity=i,level=12}).ToArray();return n;});yield return null;
   foreach(string language in new[]{"de","en"}){game.Act(s=>{var n=s.Copy();n.Settings.language=language;return n;});game.Show("hardware");yield return new WaitForSecondsRealtime(.1f);foreach(int width in new[]{320,390,430}){WorkshopTests.Capture(width,width==320?568:width==390?844:932,output+"/labor-"+language+"-"+width+".png");yield return null;}
    game.Show("items");yield return null;game.WorkshopView.ChangeMode("inventory");yield return new WaitForSecondsRealtime(.1f);foreach(int width in new[]{320,390,430}){WorkshopTests.Capture(width,width==320?568:width==390?844:932,output+"/items-"+language+"-"+width+".png");yield return new WaitForSecondsRealtime(.1f);}
    Assert.That(game.State.Workshop.inventory.Length,Is.EqualTo(6));game.WorkshopView.OpenItem("design-1");yield return new WaitForSecondsRealtime(.1f);foreach(int width in new[]{320,390,430}){WorkshopTests.Capture(width,width==320?568:width==390?844:932,output+"/detail-"+language+"-"+width+".png");yield return new WaitForSecondsRealtime(.1f);}
    Assert.That(game.WorkshopView.DetailPortrait.Frame.color,Is.EqualTo(ItemPortrait.RarityColor(1)));game.WorkshopView.CloseDetail();game.Show("hardware");yield return null;
   }
   game.HardwareTab.onClick.Invoke();yield return null;Assert.That(game.CurrentTab,Is.EqualTo("hardware"));game.GetComponent<MobileShell>().Laboratory.Train.onClick.Invoke();yield return null;Assert.That(game.CurrentTab,Is.EqualTo("training"));game.Show("hardware");yield return null;
   game.Show("items");yield return null;game.WorkshopView.ChangeMode("inventory");game.WorkshopView.OpenItem("design-0");yield return new WaitForSecondsRealtime(.1f);var equip=game.WorkshopView.DetailActions.GetComponentsInChildren<Button>().First(b=>b.name.StartsWith("equip-"));Assert.That(equip.interactable,Is.True);equip.onClick.Invoke();Assert.That(game.State.Workshop.equipped.Contains("design-0"),Is.True);yield return SceneManager.LoadSceneAsync("IdleIntelligence");yield return null;game=UnityEngine.Object.FindFirstObjectByType<GameRuntime>();Assert.That(game.State.Workshop.equipped.Contains("design-0"),Is.True);game.Show("items");yield return null;game.WorkshopView.ChangeMode("inventory");yield return new WaitForSecondsRealtime(.1f);WorkshopTests.Capture(390,844,output+"/equipped-reloaded.png");
   var read=new AtomicSaveStore(game.SavePath,new UnitySaveCodec()).Load(game.State.SavedAt);Assert.That(read.Writable,Is.True);Assert.That(read.State.Workshop.inventory.Length,Is.EqualTo(6));Assert.That(read.State.Legacy.prepared,Is.True);
  }
  [UnityTest]public IEnumerator RecordRealTapAndOverdrive(){string output="/tmp/idle-design-motion";Directory.CreateDirectory(output);game.Act(s=>{var n=s.Copy();n.Legacy.prepared=true;n.Story.seen=NarrativeCatalog.Dialogues.Select(d=>d.Id).ToArray();n.Story.enabled=false;n.Hardware[0]=10;n.Charge=99;return n;});game.Show("hardware");yield return null;var times=new System.Collections.Generic.List<float>();for(int i=0;i<60;i++){times.Add(Time.realtimeSinceStartup);if(i==8)game.TapButton.onClick.Invoke();WorkshopTests.Capture(390,844,output+"/"+i.ToString("D4")+".png");yield return new WaitForSecondsRealtime(.05f);}File.WriteAllLines(output+"/times.txt",times.Select(t=>t.ToString("R",System.Globalization.CultureInfo.InvariantCulture)));Assert.That(game.State.Overdrives,Is.GreaterThan(0));Assert.That(game.State.ActiveUntil,Is.GreaterThan(game.State.SavedAt));game.Act(s=>{var n=s.Copy();n.Workshop.reducedMotion=true;n.Settings.effects=false;return n;});yield return null;Assert.That(game.GetComponent<MobileShell>().Laboratory.Art.localScale,Is.EqualTo(Vector3.one));WorkshopTests.Capture(390,844,output+"/reduced.png");}
  public static void CheckGeometry(int width,int height,Camera camera,string path){Assert.That(GameObject.Find("LaboratoryStage").GetComponent<LayoutElement>().preferredHeight,Is.EqualTo((float)height/width<1.9f?142:218),"Responsive stage uses the actual current viewport");var names=new[]{"HardwareTab","TrainingTab","ResearchTab","ItemsTab","PrestigeTab","Save"};var measurements=new System.Collections.Generic.List<string>();foreach(var name in names){var rect=GameObject.Find(name).GetComponent<RectTransform>();var corners=new Vector3[4];rect.GetWorldCorners(corners);var min=RectTransformUtility.WorldToScreenPoint(camera,corners[0]);var max=RectTransformUtility.WorldToScreenPoint(camera,corners[2]);Assert.That(max.y-min.y,Is.GreaterThanOrEqualTo(43.5f),name+" actual pixel touch height at "+width);Assert.That(min.x,Is.GreaterThanOrEqualTo(-.5f),name);Assert.That(max.x,Is.LessThanOrEqualTo(width+.5f),name);Assert.That(min.y,Is.GreaterThanOrEqualTo(-.5f),name);Assert.That(max.y,Is.LessThanOrEqualTo(height+.5f),name);measurements.Add(name+" "+min+" "+max);}File.WriteAllLines(path+".geometry.txt",measurements);}
 }
}
